class MockEntriesRepository extends Mock implements EntriesRepository {}

Entry _buildEntry({
  required String id,
  DateTime? occurredAt,
  EntrySource source = EntrySource.manual,
}) => Entry(
  id: id,
  content: 'content-$id',
  source: source,
  chatMessageId: null,
  occurredAt: occurredAt ?? DateTime(2026, 1, 1),
  tags: const [],
  piiStatus: PiiStatus.pending,
