33	
34	  void stubRequestSuccess(dynamic responseData, {int statusCode = 200}) {
35	    when(
36	      () => dio.request<Map<String, dynamic>>(
37	        any(),
38	        data: any(named: 'data'),
39	        queryParameters: any(named: 'queryParameters'),
40	        options: any(named: 'options'),
41	      ),
42	    ).thenAnswer(
43	      (_) async => Response<Map<String, dynamic>>(
44	        requestOptions: RequestOptions(path: ''),
45	        statusCode: statusCode,
46	        data: responseData as Map<String, dynamic>?,
47	      ),
48	    );
49	  }
50	
