52	    when(
53	      () => dio.request<Map<String, dynamic>>(
54	        any(),
55	        data: any(named: 'data'),
56	        queryParameters: any(named: 'queryParameters'),
57	        options: any(named: 'options'),
58	      ),
59	    ).thenThrow(exception);
60	  }
61	
62	  group('URL construction', () {
63	    test('builds {FUNCTIONS_BASE_URL}/<function>', () async {
64	      stubRequestSuccess({'data': <String, dynamic>{}});
65	
66	      await client.call('auth-login', method: 'POST');
