92	          options: any(named: 'options'),
93	        ),
94	      ).called(1);
95	    });
96	
97	    test('passes queryParameters straight through to Dio.request() when provided', () async {
98	      stubRequestSuccess({'data': <String, dynamic>{}});
99	
100	      await client.call(
