106	      verify(
107	        () => dio.request<Map<String, dynamic>>(
108	          any(),
109	          data: any(named: 'data'),
110	          queryParameters: {'cursor': 'abc'},
111	          options: any(named: 'options'),
112	        ),
113	      ).called(1);
114	    });
115	
116	    test('omits queryParameters (sends null) when not provided', () async {
117	      stubRequestSuccess({'data': <String, dynamic>{}});
118	
119	      await client.call('entries-list', method: 'GET');
